'use strict';
// Palette assignments are product design, not validated clinical categories.
const EMOTIONS = [
 {name:'Peaceful',color:'#82ddbb',meaning:'At ease, settled, or calm'},
 {name:'Stressed',color:'#edcf71',meaning:'Under pressure or carrying too much'},
 {name:'Furious',color:'#f16b7b',meaning:'Feeling intensely angry'},
 {name:'Annoyed',color:'#eea26e',meaning:'Irritated or bothered by something'},
 {name:'Affectionate',color:'#e99bc5',meaning:'Feeling warmth or fondness'},
 {name:'Sad',color:'#88aef1',meaning:'Feeling sorrow or unhappiness'},
 {name:'Hopeful',color:'#b5abef',meaning:'Looking forward with possibility'},
 {name:'Joyful',color:'#edbcec',meaning:'Feeling delight or happiness'},
 {name:'Anxious',color:'#d8bf79',meaning:'Worried or apprehensive'},
 {name:'Lonely',color:'#879adb',meaning:'Missing connection or company'},
 {name:'Grateful',color:'#95d9cb',meaning:'Appreciative of someone or something'},
 {name:'Overwhelmed',color:'#e2ba79',meaning:'Feeling more than you can manage right now'},
 {name:'Uncertain',color:'#b1bacf',meaning:'Unsure of what you feel or what comes next'},
 {name:'Disappointed',color:'#9fa8db',meaning:'Something did not turn out as you hoped'},
 {name:'Excited',color:'#eea8ce',meaning:'Energized by something you anticipate'},
 {name:'Content',color:'#a3d6b7',meaning:'Feeling comfortable with this moment'},
 {name:'Guilty',color:'#b99cce',meaning:'Troubled by something you did or did not do'},
 {name:'Embarrassed',color:'#d699ad',meaning:'Feeling exposed or self-conscious'}
];
const $=id=>document.getElementById(id);
const input=$('emotionInput'), picker=$('picker'), options=$('emotionOptions');
let selected=null, visible=EMOTIONS, active=-1, memories=[], deviceStorage=false, pendingDelete=null, toastTimer;
const STORAGE_KEY='afterglow.memories.v1';
function notify(message){$('status').textContent=message;$('status').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('status').hidden=true,4200);}
function updateStorageLabel(){$('storageLabel').textContent=deviceStorage?'Device only · nothing sent to a server':'Session only · nothing sent to a server';$('rememberDevice').checked=deviceStorage;}
try{const saved=localStorage.getItem(STORAGE_KEY);if(saved){const parsed=JSON.parse(saved);if(Array.isArray(parsed)){memories=parsed.filter(m=>typeof m.id==='string'&&EMOTIONS.some(e=>e.name===m.emotion)&&typeof m.context==='string'&&m.context.length<=4000&&Number.isFinite(Date.parse(m.at))).slice(0,500);deviceStorage=true;}}}catch{notify('Device storage is unavailable. Memories will stay in this session.');}
updateStorageLabel();
function persist(next){if(deviceStorage){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(next));}catch{notify('Could not save to this device. Your changes have not been applied.');return false;}}memories=next;$('count').textContent=memories.length;return true;}
function renderOptions(query=''){visible=EMOTIONS.filter(e=>e.name.toLowerCase().includes(query.toLowerCase().trim()));active=-1;input.removeAttribute('aria-activedescendant');options.replaceChildren();visible.forEach((e,i)=>{const li=document.createElement('li');li.id='emotion-'+i;li.setAttribute('role','option');li.setAttribute('aria-selected','false');const dot=document.createElement('span');dot.className='dot';dot.style.setProperty('--swatch',e.color);li.append(dot,document.createTextNode(e.name));li.addEventListener('pointerdown',ev=>ev.preventDefault());li.addEventListener('click',()=>choose(e));options.append(li);});$('noMatches').hidden=visible.length>0;}
function openPicker(){renderOptions(selected&&input.value.toLowerCase()===selected.name.toLowerCase()?'':input.value);picker.hidden=false;input.setAttribute('aria-expanded','true');}
function closePicker(){picker.hidden=true;input.setAttribute('aria-expanded','false');input.removeAttribute('aria-activedescendant');}
function choose(e){selected=e;input.value=e.name.toLowerCase();document.documentElement.style.setProperty('--accent',e.color);const n=parseInt(e.color.slice(1),16);document.documentElement.style.setProperty('--accent-rgb',`${n>>16},${(n>>8)&255},${n&255}`);$('selectedMeaning').textContent=e.meaning;$('contextStep').hidden=false;closePicker();document.querySelectorAll('.quick-feelings button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.emotion===e.name)));burst(innerWidth*.5,innerHeight*.62,e.color);}
input.addEventListener('focus',openPicker);input.addEventListener('input',()=>{selected=null;$('contextStep').hidden=true;openPicker();document.querySelectorAll('.quick-feelings button').forEach(b=>b.setAttribute('aria-pressed','false'));});$('pickerToggle').onclick=()=>{if(picker.hidden){input.focus();openPicker();}else closePicker();};
input.addEventListener('keydown',e=>{if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();if(picker.hidden)openPicker();if(!visible.length)return;active=(active+(e.key==='ArrowDown'?1:-1)+visible.length)%visible.length;[...options.children].forEach((li,i)=>li.setAttribute('aria-selected',String(i===active)));input.setAttribute('aria-activedescendant','emotion-'+active);options.children[active].scrollIntoView({block:'nearest'});}else if(e.key==='Enter'){e.preventDefault();if(!picker.hidden&&visible.length){choose(visible[active<0?0:active]);$('context').focus();}}else if(e.key==='Escape')closePicker();else if(e.key==='Tab')closePicker();});
document.addEventListener('pointerdown',e=>{if(!e.target.closest('.checkin'))closePicker();});$('changeEmotion').onclick=()=>{input.focus();openPicker();input.select();};
const quick=document.querySelector('.quick-feelings');['Peaceful','Stressed','Annoyed','Sad','Hopeful'].forEach(name=>{const e=EMOTIONS.find(e=>e.name===name),b=document.createElement('button');b.dataset.emotion=name;b.setAttribute('aria-pressed','false');b.style.setProperty('--swatch',e.color);const dot=document.createElement('span');dot.className='dot';b.append(dot,document.createTextNode(name));b.onclick=()=>choose(e);quick.append(b);});
$('saveMemory').onclick=()=>{if(!selected)return;if(memories.length>=500){notify('This prototype holds 500 moments. Delete a moment before adding another.');return;}const m={id:crypto.randomUUID(),emotion:selected.name,context:$('context').value.trim(),at:new Date().toISOString()};if(!persist([m,...memories]))return;const color=selected.color;selected=null;input.value='';$('context').value='';$('contextStep').hidden=true;document.querySelectorAll('.quick-feelings button').forEach(b=>b.setAttribute('aria-pressed','false'));burst(innerWidth*.5,innerHeight*.55,color);notify(deviceStorage?'Moment saved on this device.':'Moment kept for this session.');input.focus();closePicker();};
function openDialog(id){closePicker();$(id).showModal();}document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
$('accountButton').onclick=()=>openDialog('accountDialog');$('aboutButton').onclick=()=>openDialog('aboutDialog');$('memoriesButton').onclick=()=>{renderMemories();openDialog('memoriesDialog');};document.querySelector('.brand').onclick=e=>{e.preventDefault();document.querySelectorAll('dialog[open]').forEach(d=>d.close());input.focus();};
function renderMemories(){const list=$('memoryList');list.replaceChildren();if(!memories.length){const empty=document.createElement('div');empty.className='empty-state';empty.innerHTML='<div class="empty-star" aria-hidden="true">✧</div><h3>Your first moment belongs here.</h3><p>Name a feeling and keep it. A few words of context can help you remember what was happening.</p>';list.append(empty);return;}memories.forEach(m=>{const e=EMOTIONS.find(e=>e.name===m.emotion),card=document.createElement('article');card.className='memory-card';const head=document.createElement('div');head.className='memory-heading';const h=document.createElement('h3'),dot=document.createElement('span');dot.className='dot';dot.style.setProperty('--swatch',e.color);h.append(dot,document.createTextNode(e.name));const time=document.createElement('time');time.dateTime=m.at;time.textContent=new Date(m.at).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});head.append(h,time);const p=document.createElement('p');p.textContent=m.context||'A feeling, without words to add.';const del=document.createElement('button');del.className='memory-delete';del.textContent='Delete moment';del.setAttribute('aria-label','Delete '+e.name+' moment from '+time.textContent);del.onclick=()=>{pendingDelete=m.id;openDialog('deleteDialog');};card.append(head,p,del);list.append(card);});}
$('confirmDelete').onclick=()=>{if(persist(memories.filter(m=>m.id!==pendingDelete))){renderMemories();$('deleteDialog').close();notify('Moment deleted.');pendingDelete=null;}};
$('rememberDevice').onchange=e=>{const requested=e.target.checked;try{if(requested)localStorage.setItem(STORAGE_KEY,JSON.stringify(memories));else localStorage.removeItem(STORAGE_KEY);deviceStorage=requested;updateStorageLabel();notify(requested?'Memories will stay on this device.':'Device copy removed. Current memories remain for this session.');}catch{e.target.checked=deviceStorage;notify('Could not change device storage. The previous setting is unchanged.');}};
$('count').textContent=memories.length;
// A lightweight pointer-driven trail field. No emotion inference or network requests.
const canvas=$('sky'),ctx=canvas.getContext('2d');
let width=innerWidth,height=innerHeight,dpr=1,stars=[],trails=[],lastPoint=null,lastMove=0,paused=matchMedia('(prefers-reduced-motion: reduce)').matches,frame=0;
function resize(){width=innerWidth;height=innerHeight;dpr=Math.min(devicePixelRatio||1,2);canvas.width=width*dpr;canvas.height=height*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);let seed=71;const rand=()=>{seed=(seed*16807)%2147483647;return seed/2147483647;};stars=Array.from({length:Math.min(160,Math.floor(width*height/6500))},()=>({x:rand()*width,y:rand()*height,r:rand()*.9+.2,a:rand()*.38+.1,p:rand()*6}));draw(performance.now());}
function addTrail(x,y,px,py,color){trails.push({x,y,px,py,color,life:1});if(trails.length>160)trails.shift();}
function burst(x,y,color){if(paused)return;for(let i=0;i<24;i++){const a=Math.random()*Math.PI*2,r=30+Math.random()*120;addTrail(x+Math.cos(a)*r,y+Math.sin(a)*r*.5,x+Math.cos(a)*r*.2,y+Math.sin(a)*r*.1,color);}}
function draw(now){ctx.clearRect(0,0,width,height);const accent=selected?.color||'#88aacc';const glow=ctx.createRadialGradient(width*.5,height*.62,0,width*.5,height*.62,width*.48);glow.addColorStop(0,accent+'0b');glow.addColorStop(1,accent+'00');ctx.fillStyle=glow;ctx.fillRect(0,0,width,height);for(const s of stars){ctx.globalAlpha=s.a*(paused?1:.8+.2*Math.sin(now*.0006+s.p));ctx.fillStyle='#d5e4ff';ctx.beginPath();ctx.arc(s.x,s.y,s.r,0,Math.PI*2);ctx.fill();}ctx.globalAlpha=1;
 // Long, soft arcs establish the palette before the first interaction.
 const lines=[{x:.08,y:.7,c:'#71c9ae',a:-.36},{x:.71,y:.18,c:'#ab9cd9',a:-.36},{x:.79,y:.72,c:'#a4b9e8',a:-.36}];for(const l of lines){ctx.save();ctx.translate(width*l.x,height*l.y);ctx.rotate(l.a);const g=ctx.createLinearGradient(-80,0,170,0);g.addColorStop(0,l.c+'00');g.addColorStop(.65,l.c+'44');g.addColorStop(1,l.c+'00');ctx.strokeStyle=g;ctx.lineWidth=1;ctx.shadowColor=l.c;ctx.shadowBlur=14;ctx.beginPath();ctx.moveTo(-80,8);ctx.quadraticCurveTo(55,-5,170,0);ctx.stroke();ctx.restore();}
 for(const t of trails){ctx.save();ctx.globalAlpha=t.life;ctx.strokeStyle=t.color;ctx.shadowColor=t.color;ctx.shadowBlur=18;ctx.lineWidth=1.4;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(t.px,t.py);ctx.quadraticCurveTo((t.px+t.x)/2,(t.py+t.y)/2-8,t.x,t.y);ctx.stroke();ctx.restore();t.life-=.014;}trails=trails.filter(t=>t.life>0);}
function animate(now){draw(now);if(!paused&&!document.hidden)frame=requestAnimationFrame(animate);}
function syncMotion(){cancelAnimationFrame(frame);$('motionButton').setAttribute('aria-pressed',String(paused));$('motionButton').textContent=paused?'Resume motion ▷':'Pause motion Ⅱ';draw(performance.now());if(!paused&&!document.hidden)frame=requestAnimationFrame(animate);}
document.addEventListener('pointermove',e=>{if(paused||document.querySelector('dialog[open]'))return;const now=performance.now();if(now-lastMove<18)return;lastMove=now;const p=lastPoint&&now-lastPoint.at<120?lastPoint:{x:e.clientX-35,y:e.clientY+15};addTrail(e.clientX,e.clientY,p.x,p.y,selected?.color||'#9fafdb');lastPoint={x:e.clientX,y:e.clientY,at:now};});
canvas.addEventListener('pointerdown',e=>{burst(e.clientX,e.clientY,selected?.color||'#9fafdb');});$('motionButton').onclick=()=>{paused=!paused;syncMotion();};document.addEventListener('visibilitychange',syncMotion);window.addEventListener('resize',resize);resize();syncMotion();
